# Cuaderno docente: explicacion -> ejemplo -> decision, sin conocimientos de R.
spaced_labels <- function(d, x, y, priority, max_labels = 10L) {
  if (!nrow(d)) return(integer())
  nx <- (d[[x]] - min(d[[x]])) / max(diff(range(d[[x]])), 1e-9)
  ny <- (d[[y]] - min(d[[y]])) / max(diff(range(d[[y]])), 1e-9)
  chosen <- integer()
  for (i in priority) {
    if (!length(chosen) || all(abs(nx[i] - nx[chosen]) > .18 | abs(ny[i] - ny[chosen]) > .075)) chosen <- c(chosen, i)
    if (length(chosen) >= max_labels) break
  }
  chosen
}

lesson_catalog <- function() list(
  load = list(meaning = c("Importar un corpus significa fijar qu\u00e9 documentos forman tu estudio. Cada fila representa un documento; las columnas contienen texto y metadatos como a\u00f1o, autores o revista. La aplicaci\u00f3n propone una correspondencia, pero el investigador debe comprobar que una columna llamada resumen contiene realmente los res\u00famenes que quiere estudiar.", "El an\u00e1lisis describe lo que entra en este archivo y supera los filtros. Una b\u00fasqueda incompleta, una base de datos o unos criterios distintos pueden cambiar los resultados aunque el m\u00e9todo sea el mismo. Importar correctamente es el primer control de validez, no solo un tr\u00e1mite de formato."),
    example = c("Si tienes id, t\u00edtulo y resumen, abre el visor y comprueba tres registros. El identificador permite rastrear un art\u00edculo; el t\u00edtulo ayuda a reconocerlo; el resumen contiene el texto que vamos a analizar. Si eliges t\u00edtulos como texto, tus resultados describir\u00e1n t\u00edtulos: son m\u00e1s breves y no contienen toda la informaci\u00f3n de los art\u00edculos."),
    action = c("Confirma texto y metadatos, comprueba acentos y conserva la b\u00fasqueda, fuente y fecha de extracci\u00f3n. Si las columnas aparecen unidas, revisa el separador del CSV. Si un a\u00f1o o una cita no se reconoce, consulta cobertura: la aplicaci\u00f3n no convierte un valor ausente en cero. Para varios idiomas puedes revisar etiquetas y asignarlas dentro de Preparaci\u00f3n.")),
  prepare = list(meaning = c("Preparar es decidir qu\u00e9 documentos y qu\u00e9 formas del texto van a intervenir en los c\u00e1lculos. La app aplica filtros de registros, detecta duplicados y, si lo solicitas, toma una muestra. Despu\u00e9s segmenta y normaliza el texto, anota lemas o categor\u00edas si lo has elegido y aplica criterios de vocabulario. El original se conserva para contrastar cada transformaci\u00f3n.", "Reducir ruido significa retirar elementos que no ayudan a la pregunta: por ejemplo, correos en un resumen o una palabra que viene de una plantilla repetida. Conservar informaci\u00f3n significa evitar que esos filtros borren diferencias importantes. No hay un filtro universal que separe autom\u00e1ticamente lo \u00fatil de lo in\u00fatil."),
    example = c("De 100 registros, un filtro temporal deja 90 y la deduplicaci\u00f3n elimina cinco repeticiones: quedan 85. Si despu\u00e9s eliges una muestra del 50%, se conservan 42. La presencia de una palabra usa esos 42 documentos como denominador, incluso si alguno no aporta palabras. El vocabulario de los modelos puede ser menor que el vocabulario inicialmente encontrado."),
    action = c("Para la primera ejecuci\u00f3n conserva todo el corpus y cambia solo una decisi\u00f3n cada vez. Revisa la auditor\u00eda de registros y los motivos de exclusi\u00f3n de t\u00e9rminos. Si una palabra crucial desaparece, localiza qu\u00e9 regla la excluy\u00f3 y contrasta una ejecuci\u00f3n con esa regla modificada. Al cambiar columnas, filtros o asignaciones de idioma, pulsa de nuevo Preparar corpus antes de usar resultados.")),
  lemma = list(meaning = c("El modelo ling\u00fc\u00edstico debe corresponder al idioma del texto: analizar ingl\u00e9s con un modelo espa\u00f1ol puede producir lemas o categor\u00edas incorrectas. Si todos los textos seleccionados est\u00e1n en ingl\u00e9s, elige Ingl\u00e9s aunque los art\u00edculos est\u00e9n escritos en varias lenguas. Si los textos seleccionados tienen varios idiomas, elige Varios idiomas / estimaci\u00f3n autom\u00e1tica con CLD2. CLD2 examina cada documento en este ordenador y asigna las lenguas compatibles en los casos suficientemente claros. No env\u00eda textos a Google y no necesita una columna de idioma.", "Una etiqueta reconocida del CSV se conserva y una correcci\u00f3n manual tiene prioridad sobre ella y sobre CLD2. Revisa las discrepancias: la columna puede describir el idioma del art\u00edculo, pero el resumen seleccionado puede estar traducido. Los idiomas estimados son decisiones documentadas, no verdades confirmadas. El indicador fiable es una regla del detector; el porcentaje de predominio representa texto clasificado, no probabilidad de acierto. Para asignar autom\u00e1ticamente se exigen 40 letras, una estimaci\u00f3n fiable y al menos 90% en una lengua compatible.", "Un lema es una forma de diccionario. Lematizar re\u00fane determinadas flexiones, como estudiante y estudiantes, y algunas conjugaciones. Esto reduce la dispersi\u00f3n entre formas del mismo t\u00e9rmino. No traduce, no identifica todos los sin\u00f3nimos y no garantiza acierto en siglas, nombres o vocabulario especializado."),
    example = c("Tienes mil res\u00famenes largos, algunos espa\u00f1oles y otros ingleses, sin columna idioma. CLD2 puede asignar autom\u00e1ticamente los casos claros a es y en. La tabla abre solo los pendientes; los resueltos se pueden consultar con Todas las filas. Un texto como 75 % no aporta evidencia para detectar lengua y queda pendiente. Un resumen neerland\u00e9s puede detectarse correctamente, pero esta app no tiene ese lematizador: no lo cambia por ingl\u00e9s ni espa\u00f1ol.", "Si un documento mezcla de forma sustancial ingl\u00e9s y espa\u00f1ol, la app no fuerza autom\u00e1ticamente un modelo \u00fanico. Revisa el texto y documenta c\u00f3mo tratarlo. En los estudiantes estudian, un modelo espa\u00f1ol puede obtener estudiante y estudiar; en ingl\u00e9s, studies puede convertirse en study. Calidad y quality siguen siendo t\u00e9rminos diferentes: usar dos lematizadores no vuelve comparables las lenguas como si fueran traducciones."),
    action = c("Abre Revisar idiomas / solo pendientes y resuelve esos casos leyendo sus extractos. Consulta tambi\u00e9n las discrepancias y una muestra de las asignaciones autom\u00e1ticas. Puedes corregir varias filas a la vez. Cambiar el texto seleccionado recalcula estimaciones y retira correcciones hechas para el texto anterior. Preparar modelos necesarios muestra qu\u00e9 lematizadores hacen falta; despu\u00e9s pulsa Preparar corpus. El ZIP conserva las estimaciones, su origen, las correcciones y los idiomas efectivamente aplicados para repetirlos sin reestimaci\u00f3n.", "Stemming y lematizaci\u00f3n son distintos. El stemming recorta formas mediante reglas y puede devolver una ra\u00edz que no sea palabra, como univers a partir de universities. La lematizaci\u00f3n busca una forma ling\u00fc\u00edstica interpretable. Esta app no aplica stemming; si importas texto ya stemmizado, contar\u00e1 las ra\u00edces presentes y debes documentar esa preparaci\u00f3n previa.")),
  tokens = list(meaning = c("Un token es una unidad que produce una regla de segmentaci\u00f3n del texto. En estudiante estudiante hay dos apariciones o tokens y un solo t\u00e9rmino distinto; si varias formas se re\u00fanen por su lema, se suman sus apariciones bajo ese lema. Seg\u00fan la regla, puede ser una palabra, un n\u00famero, un signo o incluso parte de una palabra. El texto 75 % puede dar dos tokens, uno o una representaci\u00f3n distinta. Por eso token no equivale siempre a palabra.", "Aqu\u00ed analizamos unidades l\u00e9xicas: secuencias de letras o n\u00fameros, con algunas marcas internas como ap\u00f3strofos. La puntuaci\u00f3n marca fronteras. Por defecto se excluyen los n\u00fameros aislados, de modo que 75 % no se estudia como una palabra tem\u00e1tica. Si activas lemas, contamos sus formas normalizadas; un token sigue siendo una aparici\u00f3n, aunque varias formas se re\u00fanan bajo un mismo t\u00e9rmino.", "Frecuencia pregunta cu\u00e1ntas veces aparece un t\u00e9rmino. Presencia pregunta en cu\u00e1ntos documentos distintos aparece. TF-IDF a\u00f1ade otra pregunta: \u00bfqu\u00e9 peso tiene en un texto y cu\u00e1nto ayuda a distinguirlo de los dem\u00e1s? Una palabra frecuente en todos los textos puede describir el campo, pero apenas distinguir unos documentos de otros. Una palabra que ocupa parte de pocos textos puede resultar m\u00e1s espec\u00edfica de esos textos."),
    example = c("Tres res\u00famenes tienen 100 palabras retenidas cada uno. Estudio aparece cinco veces en cada resumen: frecuencia 15 y presencia tres documentos. Hospital aparece tres veces en uno solo: frecuencia tres y presencia un documento. Con frecuencia gana estudio; con capacidad para distinguir textos, hospital puede ser m\u00e1s informativa.", "TF calcula la proporci\u00f3n dentro del texto. Para hospital son 3 de 100 palabras: 0,03. IDF aumenta cuando el t\u00e9rmino aparece en menos unidades; aqu\u00ed es log(3/1), aproximadamente 1,10. En ese resumen, TF \u00d7 IDF es aproximadamente 0,033. En los otros dos vale cero porque hospital no aparece. El promedio sobre los tres es aproximadamente 0,011.", "Para estudio, IDF es log(3/3)=0: el t\u00e9rmino no distingue esos tres textos. Esto no significa que sea irrelevante cient\u00edficamente ni que haya que borrarlo. Significa que todos comparten su presencia en este corpus. TF-IDF es un peso descriptivo que depende del corpus y de c\u00f3mo has definido sus unidades."),
    action = c("Primero compara las barras de los mismos t\u00e9rminos: apariciones, documentos y TF-IDF medio cuentan aspectos distintos. El selector indica si se muestran los m\u00e1s frecuentes, m\u00e1s presentes o de mayor TF-IDF; la cantidad y el estado del vocabulario tambi\u00e9n se muestran. El mapa adicional sit\u00faa todos los t\u00e9rminos evaluados, sin etiquetas amontonadas. Localizar un t\u00e9rmino abre sus cifras y permite marcar su posici\u00f3n; no lo convierte en mejor t\u00e9rmino.", "Para reducir ruido, empieza con criterios que puedas justificar: longitud, presencia m\u00ednima y lista de palabras vac\u00edas. Examina qu\u00e9 se pierde antes de aplicar filtros de TF-IDF o entrop\u00eda. Una palabra de presencia alta puede ser central para tu pregunta. Un t\u00e9rmino de TF-IDF alto puede ser una errata o muy espec\u00edfico de un solo texto. Contrasta siempre los originales."),
    worked=data.frame(Documento=c("Resumen A","Resumen B","Resumen C"),"Tokens retenidos"=c(100,100,100),"Estudio / apariciones"=c(5,5,5),"Hospital / apariciones"=c(3,0,0),"TF de hospital"=c(.03,0,0),"TF-IDF de hospital"=round(c(.03*log(3),0,0),4),check.names=FALSE),study=c("En el indicador de Preparaci\u00f3n, N es el n\u00famero de unidades que aportan tokens antes del filtro de vocabulario; df cuenta unidades con el t\u00e9rmino. Cada TF-IDF ausente aporta cero al promedio. Si eliges frases, esa unidad pasa de documento a frase. La presencia sigue contando documentos y su porcentaje usa todos los documentos preparados, incluidos los que no aportan palabras.")),
  explore = list(meaning = c("Los indicadores describen el corpus preparado. Producci\u00f3n cuenta documentos por a\u00f1o; fuentes y autores cuentan en qu\u00e9 publicaciones o firmas aparecen; citas registradas provienen de la base y fecha de extracci\u00f3n. Cada resultado necesita saber qu\u00e9 registros aportan datos y cu\u00e1l es su denominador.", "Cobertura es disponibilidad de informaci\u00f3n. Si falta el a\u00f1o de un documento, no sabemos d\u00f3nde situarlo en el tiempo. Si falta su n\u00famero de citas, no sabemos si recibi\u00f3 cero o si el dato no se export\u00f3. Los resultados con esa informaci\u00f3n se calculan solo sobre registros v\u00e1lidos, y la cobertura permite reconocer el l\u00edmite."),
    example = c("Un art\u00edculo firmado por Ana y Luis a\u00f1ade un documento al ranking de cada uno. Los porcentajes de autores pueden sumar m\u00e1s de 100% porque hay colaboraci\u00f3n. Si diez art\u00edculos tienen citas y otros cinco no tienen ese dato, la media utiliza diez observaciones; imputar cero a los cinco desconocidos cambiar\u00eda indebidamente el resultado."),
    action = c("Lee la cobertura antes del ranking y comprueba los documentos que explican los primeros puestos. Diferencia citas recibidas de referencias citadas: el primer dato viene de una base; el segundo es la bibliograf\u00eda que el documento utiliza. Ninguno, por s\u00ed solo, demuestra calidad. Para relaciones entre entidades usa la red y revisa su definici\u00f3n.")),
  models = list(meaning = c("Un modelo transforma el corpus en una representaci\u00f3n que facilita estudiar patrones. LDA resume mezclas de temas; UMAP/HDBSCAN busca grupos de documentos pr\u00f3ximos en una representaci\u00f3n; ACP resume variaci\u00f3n de pesos l\u00e9xicos; correspondencias compara perfiles de conteos. No ofrecen la misma respuesta ni un ranking \u00fanico de calidad."),
    example = c("Un resumen sobre hospitales sostenibles puede combinar dos temas en LDA y pertenecer a un \u00fanico grupo, o quedar sin asignar, en HDBSCAN. ACP o correspondencias pueden mostrar vocabulario que distingue documentos sin asignarles un tema. Estas diferencias reflejan preguntas y supuestos distintos, no un fallo por no coincidir."),
    action = c("Elige por la pregunta que necesitas responder, consulta cobertura y lee textos. Conserva ejecuciones con decisiones justificadas para estudiar sensibilidad. Una gr\u00e1fica atractiva o un porcentaje alto de varianza no demuestra validez tem\u00e1tica. Las etiquetas interpretativas requieren trabajo del investigador, con o sin asistencia de IA.")),
  lda = list(meaning = c("LDA aprende patrones de palabras que tienden a aparecer conjuntamente y representa cada documento como una mezcla de esos patrones. Los llama Tema 1, Tema 2 y as\u00ed sucesivamente. Esos n\u00fameros no significan educaci\u00f3n, salud o sostenibilidad; el modelo no sabe que una etiqueta humana sea correcta.", "Beta es la probabilidad que el modelo asigna a cada t\u00e9rmino dentro de un tema. Gamma expresa cu\u00e1nto participa cada tema en la representaci\u00f3n de un documento. Son dos distribuciones diferentes: una describe palabras, la otra mezcla de temas. Las barras de cada documento suman 100%."),
    example = c("Si un tema muestra hospital, paciente y prevenci\u00f3n, y sus documentos hablan de atenci\u00f3n sanitaria, puedes proponer esa etiqueta. Si otros textos tratan prevenci\u00f3n de riesgos laborales, la etiqueta inicial ser\u00eda demasiado estrecha. Leer palabras aisladas no basta: hay que contrastar el conjunto y tambi\u00e9n casos ambiguos.", "Un documento con 70% Tema 1 y 30% Tema 2 tiene una mezcla estimada as\u00ed por LDA. No significa que 70% de los art\u00edculos del corpus sean del Tema 1. Una beta de 0,03 describe 3% de probabilidad de ese t\u00e9rmino en la distribuci\u00f3n del tema, no 3% de documentos."),
    action = c("Usa palabras principales y varios documentos representativos para proponer nombres. Justifica qu\u00e9 evidencia apoya la etiqueta, qu\u00e9 queda fuera y c\u00f3mo la revisar\u00edas. La app no emplea un LLM para nombrar temas. El investigador debe validar cualquier sugerencia y reconocer interpretaciones alternativas.", "La prevalencia por a\u00f1o resume las mismas mezclas con los mismos temas de la ejecuci\u00f3n completa. Es una descripci\u00f3n temporal, no un LDA din\u00e1mico: no permite que cambie por a\u00f1o la distribuci\u00f3n de palabras del tema. Existen modelos din\u00e1micos espec\u00edficos; no se presentan aqu\u00ed como si fueran equivalentes.")),
  ca = list(meaning = c("Correspondencias compara c\u00f3mo se reparte el vocabulario entre unidades de texto. Dos palabras pueden tener perfiles parecidos si su presencia relativa se concentra en unidades similares. La t\u00e9cnica resume esas diferencias en ejes; el dibujo es una proyecci\u00f3n y pierde informaci\u00f3n fuera de los ejes mostrados.", "La inercia cuantifica las diferencias de perfiles que resume el an\u00e1lisis. El porcentaje de un eje indica cu\u00e1nto recoge de esa variaci\u00f3n. Cos\u00b2 indica qu\u00e9 parte de la posici\u00f3n de un objeto queda representada en el plano. Contribuci\u00f3n responde qu\u00e9 t\u00e9rminos participan m\u00e1s en construir un eje. Son preguntas diferentes."),
    example = c("Con ejes de 22% y 15%, el plano recoge 37% de la inercia y deja 63% fuera. Una palabra con cos\u00b2 0,90 puede leerse bastante mejor en ese plano que otra con 0,08. Dos palabras pr\u00f3ximas con cos\u00b2 bajo pueden parecer semejantes por la proyecci\u00f3n, aunque difieran en otros ejes."),
    action = c("Consulta primero inercia y cos\u00b2; despu\u00e9s revisa t\u00e9rminos con contribuciones altas. Lee documentos para dar significado a las diferencias del eje. No compares la inercia con la varianza ACP como si fueran la misma medida. La distancia entre una palabra y un documento en planos separados no se interpreta como una asociaci\u00f3n medida.")),
  density = list(meaning = c("Para agrupar documentos primero necesitamos una representaci\u00f3n num\u00e9rica de su texto. La ruta l\u00e9xica pondera t\u00e9rminos y resume ese vocabulario mediante LSA; una ruta alternativa importa vectores con procedencia documentada. UMAP reduce esa representaci\u00f3n intentando conservar vecindarios. HDBSCAN identifica regiones densas en las coordenadas usadas para agrupar.", "Un grupo re\u00fane documentos por el procedimiento y par\u00e1metros elegidos, no por una categor\u00eda verdadera ya conocida. El grupo cero conserva los documentos sin asignar. El mapa de dos ejes se calcula aparte para poder verlo: HDBSCAN puede haber trabajado con cinco dimensiones, aunque en pantalla solo haya dos."),
    example = c("Con cien res\u00famenes, probar diez vecinos y despu\u00e9s veinte compara qu\u00e9 sucede al ampliar el entorno considerado por UMAP. min_dist peque\u00f1o favorece compactaci\u00f3n, pero no es un radio HDBSCAN. minPts cinco y diez cambian exigencia de densidad y tama\u00f1o. Si un documento cambia de grupo, revisa su texto y los vecinos; no elijas solo el dibujo que m\u00e1s te guste."),
    action = c("La semilla controla operaciones aleatorias de UMAP y de ciertas aproximaciones LSA. HDBSCAN recibe las coordenadas resultantes y es determinista sobre una matriz fija. Por eso cambiar semilla puede cambiar los grupos: repetir no es lo mismo que demostrar estabilidad.", "La evoluci\u00f3n anual describe cu\u00e1nto pesan grupos fijos en documentos con a\u00f1o. Puedes comparar proporciones o una curva penalizada cuando haya cobertura suficiente. La tabla de palabras por a\u00f1o muestra vocabulario observado dentro del grupo, sin reentrenar un tema din\u00e1mico. Con a\u00f1os agregados no se estima estacionalidad mensual."),
    decisions = data.frame(Parametro = c("Vecinos", "Dimensiones para agrupar", "min_dist", "minPts", "Semilla"),
      "Decisi\u00f3n" = c("10 frente a 20, siempre menor que el n\u00ba de documentos", "5 frente a 10; m\u00e1s dimensiones no garantizan mejor resultado", "0 frente a 0,1; observa cambios en compactaci\u00f3n y grupos", "5 frente a 10; contrasta tama\u00f1o y documentos sin asignar", "2026 frente a 2027; comprueba sensibilidad, no solo reproducibilidad"))),
  networks = list(meaning = c("Una red representa entidades como nodos y una relaci\u00f3n definida como conexiones. Autores se conectan por coautor\u00eda; palabras por compartir documentos; referencias por cocitaci\u00f3n; documentos por referencias compartidas. Las revistas de esta app se conectan por afinidad de vocabulario. Son preguntas distintas, aunque todas se dibujen como puntos y l\u00edneas.", "La disposici\u00f3n solo ayuda a ver conexiones. Arrastrar un nodo no cambia la relaci\u00f3n medida, sus pesos ni indicadores. Las comunidades se calculan a partir del grafo, no por cercan\u00eda visual. Las m\u00e9tricas dependen de los nodos y conexiones que has conservado."),
    example = c("Un art\u00edculo de Ana, Luis y Eva genera tres parejas. Conteo completo a\u00f1ade uno a cada pareja; conteo fraccionado divide la aportaci\u00f3n total del art\u00edculo entre sus tres parejas, de modo que cada una recibe un tercio. Si despu\u00e9s limitas el dibujo a Ana y Luis, el peso sigue siendo un tercio: el l\u00edmite del gr\u00e1fico no cambia la aportaci\u00f3n original."),
    action = c("Revisa nombres y la definici\u00f3n de conexi\u00f3n antes de interpretar. Grado cuenta vecinos y fuerza suma pesos: intensidad y cantidad de colaboradores no son lo mismo. Una articulaci\u00f3n separa partes al retirarla; no prueba liderazgo. La tabla explica lecturas del grafo vigente. Para estudiar una zona extrae un subgrafo y consulta sus m\u00e9tricas recalculadas, sin confundirlas con las de la red completa."),
    decisions = data.frame(Indicador = c("Grado / fuerza", "Densidad / componentes", "Intermediaci\u00f3n", "Centralidad arm\u00f3nica", "Agrupamiento / transitividad", "Louvain / modularidad"),
      Lectura = c("N\u00ba de vecinos / suma de pesos; conectividad e intensidad son distintas", "Conexiones observadas / posibles; conjuntos conectados y aislados", "Fracci\u00f3n normalizada de rutas m\u00ednimas que atraviesa un nodo; aqu\u00ed usa saltos sin pesos", "Accesibilidad: media de inversos de distancias en saltos; inalcanzables aportan cero", "Proporci\u00f3n de tri\u00e1ngulos cerrados; local vale cero si faltan vecinos, global sin tripletas no es evaluable", "Partici\u00f3n exploratoria por pesos y grado de concentraci\u00f3n interna; no demuestra grupos sociales reales"))),
  jsd = list(title = "JSD shifts / explicar diferencias entre distribuciones", goal = "Comparar A y B, identificar palabras responsables y comprobar la cobertura.",
    meaning = c("Jensen\u2013Shannon responde cu\u00e1nto difiere el reparto de palabras entre dos conjuntos. No compara solo cu\u00e1ntas palabras o documentos tienen: compara qu\u00e9 proporci\u00f3n ocupa cada t\u00e9rmino. Antes de calcularla, cada conjunto se transforma en un reparto que suma 100%. As\u00ed podemos comparar un conjunto grande con otro peque\u00f1o sin que el tama\u00f1o, por s\u00ed solo, cree una diferencia.", "JSD vale cero cuando los repartos coinciden. Aumenta cuando los t\u00e9rminos pesan de forma distinta; llega a uno cuando los conjuntos no comparten ninguno de los t\u00e9rminos con presencia. Es una medida de diferencia l\u00e9xica del vocabulario analizado, no una medida de calidad, una prueba de significaci\u00f3n ni una explicaci\u00f3n de por qu\u00e9 ocurri\u00f3 el cambio."),
    example = c("En A hay 80 apariciones de hospital y 20 de escuela: hospital ocupa 80% y escuela 20%. En B hay 800 y 200: al dividir por sus mil apariciones se obtiene otra vez 80% y 20%. JSD es cero porque compara esos dos repartos iguales. Las cantidades absolutas son distintas, pero no la composici\u00f3n que hemos decidido medir.", "Si A solo usa hospital y B solo usa escuela, sus repartos no coinciden en ninguna palabra y JSD llega a uno. Las dos palabras explican la mitad de la diferencia cada una. En el gr\u00e1fico, hospital se coloca a la izquierda porque pesa m\u00e1s en A y escuela a la derecha porque pesa m\u00e1s en B. La direcci\u00f3n ayuda a leer; ninguna aportaci\u00f3n a la diferencia es negativa."),
    action = c("Elige A y B por una pregunta concreta y usa el mismo vocabulario y preparaci\u00f3n. Comprueba cu\u00e1ntos documentos y tokens aportan informaci\u00f3n. Tokens agrupados da m\u00e1s peso a textos largos; Documentos equilibrados compara el perfil de un documento medio. Esa elecci\u00f3n modifica lo que est\u00e1s midiendo y debe justificarse.", "Lee las palabras que explican m\u00e1s diferencia y sus documentos. Un cambio puede deberse al idioma, a la b\u00fasqueda, a la longitud o a la selecci\u00f3n del corpus. JSD no distingue autom\u00e1ticamente esas causas. Los t\u00e9rminos borrados por filtros ya no intervienen: una igualdad en el vocabulario retenido no demuestra igualdad de todos los textos."),
    sources = c("Gallagher et al. / generalized word shifts" = "https://doi.org/10.1140/epjds/s13688-021-00260-3", "Shifterator / c\u00f3digo abierto" = "https://github.com/ryanjgallagher/shifterator", "S\u00e1nchez-Franco y Rey-Tienda / art\u00edculo de referencia" = "https://doi.org/10.1108/MD-06-2023-0966"),
    worked=data.frame(Conjunto=c("A","B"),"Hospital / apariciones"=c(80,800),"Escuela / apariciones"=c(20,200),"Total de apariciones"=c(100,1000),"Hospital / porcentaje"=c(80,80),"Escuela / porcentaje"=c(20,20),check.names=FALSE),study=c("Para el c\u00e1lculo se usan proporciones P y Q de los mismos t\u00e9rminos. Su mezcla M=(P+Q)/2 da la misma importancia a los dos conjuntos. JSD promedia las diferencias de informaci\u00f3n entre P y M y entre Q y M, con logaritmos base 2; esa base expresa el resultado en bits y fija el m\u00e1ximo en uno. Los t\u00e9rminos sin aparici\u00f3n no aportan logaritmos infinitos: se usa la convenci\u00f3n cero por logaritmo de cero igual a cero.","La distancia ra\u00edz de JSD utiliza la ra\u00edz cuadrada del valor global y tiene propiedades de una distancia m\u00e9trica. No cambia los t\u00e9rminos que explican el contraste ni a\u00f1ade documentos. Las barras usan el porcentaje de aportaci\u00f3n de cada t\u00e9rmino a JSD; la suma de todas es 100% si JSD es positiva, y no se define un reparto de aportaciones cuando JSD es cero.")),
  pca = list(title = "ACP / componentes principales y perfiles l\u00e9xicos", goal = "Distinguir coordenadas, varianza, contribuci\u00f3n y calidad de representaci\u00f3n.",
    meaning = c("Un perfil TF-IDF es una fila de n\u00fameros que resume el vocabulario de un documento: hay un valor por t\u00e9rmino, y es cero si no aparece. TF-IDF pondera cu\u00e1nto se usa dentro del documento y su rareza entre documentos. El perfil no es un tema, una etiqueta ni una valoraci\u00f3n de calidad; es una representaci\u00f3n para poder comparar textos num\u00e9ricamente.", "ACP busca combinaciones de esas variables que recojan diferencias entre documentos. El primer componente resume la mayor variaci\u00f3n posible; el siguiente recoge otra parte sin repetir la primera direcci\u00f3n. El mapa muestra los dos primeros y pierde la variaci\u00f3n de los restantes."),
    example = c("Imagina perfiles con columnas hospital, escuela y energ\u00eda. Un documento puede pesar m\u00e1s en hospital y otro en escuela, sin que ninguno sea mejor. ACP encuentra direcciones que resumen esas diferencias. Si el plano recoge 50% de la varianza, queda otra mitad fuera: dos documentos pr\u00f3ximos podr\u00edan diferir en componentes que no vemos.", "El plano de documentos muestra puntuaciones. El de variables muestra correlaciones de t\u00e9rminos con los componentes, en otra escala. Una flecha y un documento no son objetos comparables por la distancia entre esos dos dibujos."),
    action = c("Empieza sin estandarizar y revisa varianza, cos\u00b2 y contribuciones. Centrar resta a cada variable su media; estandarizar adem\u00e1s divide por su desviaci\u00f3n t\u00edpica, dando peso relativo a variables de poca variaci\u00f3n. Contrasta esa decisi\u00f3n y documenta el vocabulario. Un cos\u00b2 bajo advierte que un punto est\u00e1 mal resumido en el plano.", "En ACP y LSA se usa una variante suavizada de IDF para que t\u00e9rminos presentes en todo el corpus no tengan necesariamente peso cero. El indicador descriptivo de Preparaci\u00f3n conserva log(N/df) sin suavizar. Ambas f\u00f3rmulas se documentan: no deben confundirse al reproducir cifras."),
    sources = c("R / prcomp" = "https://stat.ethz.ch/R-manual/R-devel/library/stats/html/prcomp.html")),
  export = list(meaning = c("Una entrega acad\u00e9mica debe permitir comprobar qu\u00e9 datos entraron, qu\u00e9 decisiones se aplicaron y de d\u00f3nde sale cada afirmaci\u00f3n. El ZIP conserva tablas completas, par\u00e1metros, datos exactos en RDS y c\u00f3digo. Los gr\u00e1ficos y el informe organizan la lectura; las skills ayudan a revisar y preparar borradores bajo control del investigador.", "La autor\u00eda y responsabilidad pertenecen a autores humanos. La IA no es autora ni valida resultados: cualquier cifra, referencia, interpretaci\u00f3n o texto asistido debe supervisarse exhaustivamente contra datos y fuentes. Usar una respuesta sin esa comprobaci\u00f3n puede producir errores o atribuciones falsas."),
    example = c("Un borrador dice aument\u00f3 el inter\u00e9s por la salud porque aparecen m\u00e1s documentos de un grupo. Comprueba si tambi\u00e9n aument\u00f3 la producci\u00f3n total recuperada, si cambi\u00f3 la b\u00fasqueda y si el a\u00f1o est\u00e1 completo. La cifra observada puede sostener que aument\u00f3 el n\u00famero en este corpus; no demuestra por s\u00ed sola inter\u00e9s del campo ni una causa."),
    action = c("Guarda una entrega por ejecuci\u00f3n y conserva las comprobaciones de afirmaciones. El investigador decide el argumento, revisa el m\u00e9todo y responde por la versi\u00f3n final. Documenta la asistencia de IA conforme a instituci\u00f3n y revista, y no inventes referencias ni declaraciones \u00e9ticas. Los datos permanecen locales hasta que t\u00fa decidas compartirlos."))
)

figure_explanation <- function(key) switch(key,
  law_lotka = "Cada punto rojo es la proporci\u00f3n de autores que firman ese n\u00famero de trabajos; la l\u00ednea azul es el ajuste a tu corpus y la gris discontinua, el patr\u00f3n cl\u00e1sico (exponente 2). Si los puntos siguen la l\u00ednea, el reparto es parecido al de Lotka. Ambos ejes son logar\u00edtmicos: una recta indica un patr\u00f3n de potencia.",
  law_bradford = "Las revistas se ordenan de la m\u00e1s a la menos productiva y se acumulan sus art\u00edculos. Los colores marcan tres zonas con aproximadamente un tercio de los art\u00edculos cada una. Si cada zona necesita varias veces m\u00e1s revistas que la anterior en proporci\u00f3n parecida, el reparto se acerca al de Bradford.",
  law_zipf = "Cada punto es una palabra: su rango (1 = la m\u00e1s frecuente) frente a sus apariciones, ambos ejes logar\u00edtmicos. Una recta con pendiente cercana a \u22121 es el patr\u00f3n de Zipf. La l\u00ednea azul es el ajuste a tu corpus.",
  jsd = "JSD resume la diferencia de proporciones de palabras entre A y B. Estas barras descomponen esa diferencia: una barra m\u00e1s larga identifica una palabra que explica m\u00e1s del contraste total. Las palabras que pesan m\u00e1s en A se colocan a la izquierda; las que pesan m\u00e1s en B, a la derecha. Se muestran hasta veinte t\u00e9rminos y se indica qu\u00e9 parte de la diferencia explican juntos. La direcci\u00f3n no representa una diferencia negativa.",
  jsd_cumulative = "Ordenamos todas las palabras por aportaci\u00f3n y sumamos su porcentaje de JSD. La l\u00ednea del 80% ayuda a planificar lectura; no indica significaci\u00f3n estad\u00edstica.",
  jsd_matrix = "Cada celda contiene JSD entre dos categor\u00edas del corpus vigente; diagonal 0 y matriz sim\u00e9trica. El eje usa categor\u00edas completas en tablas y c\u00f3digos si son numerosas. No es una matriz de correlaci\u00f3n.",
  jsd_time = "Cada punto compara dos a\u00f1os observados. C\u00edrculo vac\u00edo: existe un salto. No se estiman a\u00f1os sin datos ni se atribuye el cambio a un acontecimiento externo.",
  pca = "El plano de documentos resume diferencias de sus perfiles de vocabulario; el plano de variables muestra relaciones de t\u00e9rminos con los ejes, en otra escala. El color indica cu\u00e1nto de cada objeto se representa en ese plano, medido con cos\u00b2. Lee la varianza de los ejes y los originales antes de dar significado a proximidades.",
  pca_documents = "Cada punto representa un documento resumido en dos componentes. El color indica su cos\u00b2: un valor mayor significa que una parte mayor de su posici\u00f3n queda recogida en este plano. Busca un ID o t\u00edtulo para leer sus cifras y consulta cu\u00e1nta varianza recogen los dos ejes.",
  pca_terms = "Las flechas representan correlaciones de t\u00e9rminos con los componentes. Una flecha pr\u00f3xima a la circunferencia se representa mejor en estos dos ejes; una muy corta deja parte importante de su relaci\u00f3n fuera del plano. Este gr\u00e1fico tiene objetos y escala diferentes del plano de documentos.",
  pca_variance = "Las barras indican porcentaje de varianza por componente ACP. La tabla conserva todos los ejes. El gr\u00e1fico muestra hasta 12 para mantener legibilidad.",
  ca_variance = "Las barras indican porcentaje de inercia por eje de correspondencias; no es la varianza de ACP. El plano anterior solo recoge los dos primeros ejes.",
  tokens = "Las barras comparan los mismos t\u00e9rminos con tres medidas distintas. Apariciones cuenta repeticiones; documentos cuenta textos distintos; TF-IDF medio resume uso relativo y rareza. El selector y la nota de selecci\u00f3n indican exactamente qu\u00e9 t\u00e9rminos est\u00e1s viendo. El mapa adicional muestra todos los t\u00e9rminos del vocabulario elegido, con puntos de tama\u00f1o constante y sin etiquetas superpuestas.",
  lda_heatmap = "Cada barra es un documento y suma 100%. Cada color es un tema LDA. La vista inicial pagina 18 documentos en el orden de la tabla del modelo: no es una muestra aleatoria ni una selecci\u00f3n de calidad. Puedes recorrer p\u00e1ginas o buscar cualquier documento por ID, t\u00edtulo o DOI; la ampliaci\u00f3n tambi\u00e9n permite elegirlos. Las proporciones son mezclas estimadas, no porcentajes de art\u00edculos del corpus.",
  ca = "Cada punto representa un t\u00e9rmino y el plano resume diferencias de perfiles de conteos. Ambos ejes tienen la misma escala para no deformar distancias. Consulta la inercia y el cos\u00b2 de los t\u00e9rminos antes de interpretar una cercan\u00eda: fuera del plano puede haber diferencias que no vemos.",
  network = "Los nodos representan las entidades de la red elegida y las l\u00edneas sus relaciones definidas en la pantalla. El tama\u00f1o refleja documentos asociados al nodo y el color identifica una comunidad calculada. Arrastrar solo cambia la disposici\u00f3n. Las m\u00e9tricas se refieren a esta red filtrada; un subgrafo requiere recalcularlas.",
  density = "Cada punto es un documento y el color identifica su grupo HDBSCAN; los documentos sin asignar se conservan en gris. Este mapa de dos ejes es una vista independiente del espacio donde se agruparon. Pulsa un punto para leer el resumen y comprobar si la agrupaci\u00f3n tiene sentido.",
  density_membership = "La caja resume membres\u00edas del grupo: mediana, cuartiles y bigotes de 1,5 veces el rango intercuart\u00edlico. Puntos = documentos. Membres\u00eda no equivale a probabilidad tem\u00e1tica calibrada.",
  "Comprueba t\u00edtulos, unidades y denominadores. Usa la tabla para consultar cifras completas y leer documentos cuando corresponda.")
